graphql.query:
mutation {
    clearSearchHistory
}

mutation ($createApplicationInput: CreateApplicationInput!) {
    createApplication (createApplicationInput: $createApplicationInput) {
        exampleField
    }
}

mutation ($createChatInput: CreateChatInput!) {
    createChat (createChatInput: $createChatInput) {
        exampleField
    }
}

mutation ($createReviewInput: CreateReviewInput!) {
    createReview (createReviewInput: $createReviewInput) {
        comment
        createdAt
        errandId
        id
        rating
        reviewerId
        workerId
    }
}

mutation ($createWalletInput: CreateWalletInput!) {
    createWallet (createWalletInput: $createWalletInput) {
        exampleField
    }
}

mutation ($id: Int!) {
    removeApplication (id: $id) {
        exampleField
    }
}

mutation ($id: Int!) {
    removeChat (id: $id) {
        exampleField
    }
}

mutation ($id: Int!) {
    removeReview (id: $id) {
        comment
        createdAt
        errandId
        id
        rating
        reviewerId
        workerId
    }
}

mutation ($id: Int!) {
    removeWallet (id: $id) {
        exampleField
    }
}

mutation ($updateApplicationInput: UpdateApplicationInput!) {
    updateApplication (updateApplicationInput: $updateApplicationInput) {
        exampleField
    }
}

mutation ($updateChatInput: UpdateChatInput!) {
    updateChat (updateChatInput: $updateChatInput) {
        exampleField
    }
}

mutation ($updateReviewInput: UpdateReviewInput!) {
    updateReview (updateReviewInput: $updateReviewInput) {
        comment
        createdAt
        errandId
        id
        rating
        reviewerId
        workerId
    }
}

mutation ($updateWalletInput: UpdateWalletInput!) {
    updateWallet (updateWalletInput: $updateWalletInput) {
        exampleField
    }
}

query ($id: Int!) {
    application (id: $id) {
        exampleField
    }
}

query ($id: Int!) {
    chat (id: $id) {
        exampleField
    }
}

query ($input: PlaceDetailsInput!) {
    placeDetails (input: $input) {
        formattedAddress
        latitude
        longitude
    }
}

query ($id: Int!) {
    review (id: $id) {
        comment
        createdAt
        errandId
        id
        rating
        reviewerId
        workerId
    }
}

query ($id: ID!) {
    service (id: $id) {
        category {
        id
        name
        services
        type
        }
        categoryId
        id
        name
        type
    }
}

query ($input: GetServiceCategoriesInput) {
    serviceCategories (input: $input) {
        id
        name
        services {
        category
        categoryId
        id
        name
        type
        }
        type
    }
}

query ($categoryType: ServiceCategoryType) {
    services (categoryType: $categoryType) {
        category {
        id
        name
        services
        type
        }
        categoryId
        id
        name
        type
    }
}

query ($input: SuggestAddressInput!) {
    suggestAddresses (input: $input) {
        description
        placeId
    }
}

query {
    userSearchHistory {
        createdAt
        id
        keyword
        updatedAt
        workerId
    }
}

query ($id: Int!) {
    wallet (id: $id) {
        exampleField
    }
}
